def verify_isbn(isbn: str) -> str:
    def calculate_checksum(isbn: str) -> int:
        total = 0
        for i in range(12):
            total += (10 - i) * int(isbn[i])
        return total % 11

    def is_valid(isbn: str) -> bool:
        return calculate_checksum(isbn) == 0

    if not is_valid(isbn):
        isbn_digits = list(isbn[:-1])
        for i in range(10):
            isbn_digits[-1] = str(i)
            if calculate_checksum(''.join(isbn_digits)) == 0:
                return ''.join(isbn_digits) + '-' + isbn[-1]
    return "Right"

